// Verifies X-Retell-Signature. Format: "v=<unix ms>,d=<hex hmac>"
// digest = HMAC-SHA256(rawBody + timestamp, RETELL_API_KEY), timestamp must be within 5 minutes,
// compared in constant time. Source: https://docs.retellai.com/features/secure-webhook
// Requires: NODE_FUNCTION_ALLOW_BUILTIN=crypto and the Webhook node option "Raw Body" (binary property "data").
const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers || {};
const sigHeader = String(headers['x-retell-signature'] || '');
const apiKey = $env.RETELL_API_KEY || '';
let raw;
try {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} catch (e) {
  // Fallback only if raw body is unavailable; a re-serialized body may not match the signed bytes.
  raw = typeof item.json.body === 'string' ? item.json.body : JSON.stringify(item.json.body ?? {});
}
let verified = false;
let reason = 'missing_signature';
if (!apiKey) {
  reason = 'missing_api_key';
} else if (sigHeader) {
  const parts = {};
  for (const seg of sigHeader.split(',')) {
    const i = seg.indexOf('=');
    if (i > 0) parts[seg.slice(0, i).trim()] = seg.slice(i + 1).trim();
  }
  const ts = parts.v;
  const given = parts.d;
  if (!ts || !given) {
    reason = 'malformed_signature';
  } else if (Math.abs(Date.now() - Number(ts)) > 5 * 60 * 1000) {
    reason = 'stale_timestamp';
  } else {
    const expected = crypto.createHmac('sha256', apiKey).update(raw + ts).digest('hex');
    const a = Buffer.from(expected, 'utf8');
    const b = Buffer.from(given, 'utf8');
    verified = a.length === b.length && crypto.timingSafeEqual(a, b);
    reason = verified ? 'ok' : 'digest_mismatch';
  }
}
let body = item.json.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
return [{ json: { verified, reason, body: body ?? {}, headers } }];

// ---- shared helpers (duplicated in each workflow on purpose: n8n Code nodes cannot import) ----
const crypto = require('crypto');
const TZ = $env.PRACTICE_TZ || 'America/New_York';
const SALT = $env.PATIENT_HASH_SALT || '';
const envJson = (k) => { try { return JSON.parse($env[k] || '{}'); } catch (e) { return {}; } };
const sha256 = (s) => crypto.createHash('sha256').update(String(s)).digest('hex');
const patientRef = (id) => (id === null || id === undefined || id === '') ? null : sha256(String(id) + SALT);
const fmt = (d, opts) => new Intl.DateTimeFormat('en-US', Object.assign({ timeZone: TZ }, opts)).format(d);
const ordinal = (n) => n + ((n % 10 === 1 && n !== 11) ? 'st' : (n % 10 === 2 && n !== 12) ? 'nd' : (n % 10 === 3 && n !== 13) ? 'rd' : 'th');
const sayWhen = (iso) => { const d = new Date(iso); return fmt(d, { weekday: 'long' }) + ' the ' + ordinal(Number(fmt(d, { day: 'numeric' }))) + ' at ' + fmt(d, { hour: 'numeric', minute: '2-digit' }); };
const providerFirst = (id, fallbackName) => {
  const names = envJson('NEXHEALTH_PROVIDER_NAMES');
  if (id !== null && id !== undefined && names[String(id)]) return names[String(id)];
  if (fallbackName) { const parts = String(fallbackName).replace(/^(dr\.?|doctor)\s+/i, '').trim().split(/\s+/); return parts.length ? 'Dr. ' + parts[parts.length - 1] : null; }
  return null;
};
const e164 = (p) => { if (!p) return null; let d = String(p).replace(/[^\d+]/g, ''); if (d.startsWith('+')) return d; d = d.replace(/\D/g, ''); if (d.length === 10) return '+1' + d; if (d.length === 11 && d.startsWith('1')) return '+' + d; return d ? '+' + d : null; };
// ---- end helpers ----

// TODO (verify against a live payload): Retell's inbound SMS webhook event "chat_inbound" carries
// { chat_inbound: { chat_id, agent_id, from_number, to_number } } and, per docs as of 2026-09, no message text.
// This node checks every plausible text field (chat_inbound, chat_analyzed chat object, generic body). If the text is
// never present, wire the SMS agent's custom function "sms_opt_out" to this same webhook instead.
const body = $json.body || {};
const ci = body.chat_inbound || {};
const chat = body.chat || {};
const candidates = [body.message, body.text, body.content, body.body, ci.message, ci.text, ci.content, ci.body];
if (Array.isArray(chat.message_with_tool_calls)) {
  const users = chat.message_with_tool_calls.filter(m => m && m.role === 'user' && typeof m.content === 'string');
  if (users.length) candidates.unshift(users[users.length - 1].content);
}
if (typeof chat.transcript === 'string') {
  const lines = chat.transcript.split('\n').filter(l => /^user:/i.test(l.trim()));
  if (lines.length) candidates.unshift(lines[lines.length - 1].trim().replace(/^user:\s*/i, ''));
}
if (body.args && typeof body.args.message === 'string') candidates.unshift(body.args.message);   // custom-function route
const text = candidates.find(c => typeof c === 'string' && c.trim().length) || '';
const from = e164(ci.from_number || chat.from_number || body.from_number || (body.call && body.call.from_number) || null);
const to = e164(ci.to_number || chat.to_number || body.to_number || (body.call && body.call.to_number) || null);
const is_stop = /^\s*(STOP|QUIT|END|REVOKE|OPT ?OUT|CANCEL|UNSUBSCRIBE)\s*$/i.test(text);
return [{ json: {
  is_stop, text_present: !!text, event: body.event || null,
  from_number: from, to_number: to,
  phone_hash: from ? sha256(from + SALT) : null, phone_last4: from ? from.slice(-4) : null,
  chat_id: ci.chat_id || chat.chat_id || body.chat_id || null,
} }];
